files.content:
.ds .ds-token-typography { display:grid; gap:var(--p-space-xs); justify-items:start; }
.ds .ds-token-type { font:var(--p-type-display); letter-spacing:var(--p-tracking-tighter); }
.ds .ds-token-sizes { display:flex; align-items:baseline; gap:var(--p-space-md); font-family:var(--p-font); }
.ds .ds-token-sizes [data-token="sm"] { font-size:var(--p-text-sm); }
.ds .ds-token-sizes [data-token="md"] { font-size:var(--p-text-md); }
.ds .ds-token-sizes [data-token="lg"] { font-size:var(--p-text-lg); }
